DROP TABLE IF EXISTS `dim_country`;
CREATE TABLE "dim_country" (
"id" INTEGER,
  "country_code" TEXT,
  "country" TEXT,
  "region" TEXT,
  "income_group" TEXT,
  "created_at" TIMESTAMP
);
DROP TABLE IF EXISTS `fact_economic_data`;
CREATE TABLE "fact_economic_data" (
"id" INTEGER,
  "country_code" TEXT,
  "year" INTEGER,
  "population" INTEGER,
  "population_million" REAL,
  "gdp" REAL,
  "gdp_billion" REAL,
  "gdp_per_capita" REAL,
  "unemployment_rate" REAL,
  "life_expectancy" REAL,
  "created_at" TIMESTAMP
);
DROP TABLE IF EXISTS `fact_education_data`;
CREATE TABLE "fact_education_data" (
"id" INTEGER,
  "country_code" TEXT,
  "year" INTEGER,
  "school_enrollment_primary" REAL,
  "school_enrollment_secondary" REAL,
  "literacy_rate_adult" REAL,
  "govt_expenditure_education" REAL,
  "created_at" TIMESTAMP
);
DROP TABLE IF EXISTS `fact_health_data`;
CREATE TABLE "fact_health_data" (
"id" INTEGER,
  "country_code" TEXT,
  "year" INTEGER,
  "health_expenditure_pct_gdp" REAL,
  "health_expenditure_per_capita" REAL,
  "infant_mortality_rate" REAL,
  "hospital_beds_per_1000" REAL,
  "created_at" TIMESTAMP
);
